/**
 * @file Report data-token consumers that need an ownership migration.
 *
 * @input Consumer JavaScript/TypeScript source and generated theme CSS
 * @output An upgrade error for stale generated root-default artifacts. In a
 *   project that compiles Astryx source (its package.json, or an ancestor's
 *   up to the repository root, declares `@astryxdesign/build`), one TODO
 *   comment per file at the first fallback-less `var(--color-data-*)` use
 *   (in JS strings, embedded or whole, and in CSS). Prebuilt projects get
 *   no report for those uses: `@astryxdesign/core/astryx.css` defines all 56
 *   defaults.
 * @position Next-release upgrade validation for spec:AST-066 FR18/FR19
 *
 * Comments are the codemod's only non-failing report channel (`api.report`
 * is a stub), and each is added once, so a second run changes nothing.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';

export const meta = {
  title: 'Validate data-token ownership',
  description:
    'Fails on stale generated theme CSS that still owns root data defaults. In projects that compile Astryx source with @astryxdesign/build, marks the first fallback-less data-token var() use in each source file or stylesheet with a TODO, since those defaults exist only when a compiled dataVars import retains them; prebuilt projects get the defaults from @astryxdesign/core/astryx.css and are left unchanged.',
  fileExtensions: ['.tsx', '.ts', '.jsx', '.js', '.mjs', '.cjs', '.css'],
};

// A use without a fallback; `var(--color-data-x, <fallback>)` stays valid.
const DIRECT_DATA_VAR = /var\(\s*(--color-data-[a-z0-9-]+)\s*\)/u;
const CSS_COMMENT = /\/\*[\s\S]*?\*\//gu;
const GENERATED_THEME_HEADER = '@generated by `astryx theme build`';
const ROOT_DATA_DECLARATION = /:root\s*\{[^}]*--color-data-/su;

// The source build is the only supported way to compile Astryx package
// source (spec:AST-080 FR5); every other setup loads the prebuilt stylesheets.
const SOURCE_BUILD_PACKAGE = '@astryxdesign/build';
const DEPENDENCY_FIELDS = [
  'dependencies',
  'devDependencies',
  'optionalDependencies',
];
const REPOSITORY_ROOT_MARKERS = ['.git', '.hg', '.sl'];

const TODO_MARKER =
  'TODO(astryx upgrade): var(--color-data-*) without a fallback';
const TODO_TEXT =
  `${TODO_MARKER}. This project compiles Astryx source with ` +
  '@astryxdesign/build, where the data-color defaults exist only when a ' +
  'compiled dataVars import retains them. If the app loads ' +
  '@astryxdesign/core/astryx.css, they are defined; otherwise import dataVars ' +
  'from @astryxdesign/core/theme/dataTokens.stylex in CSS-capable code, or ' +
  'add a fallback. Canvas and other non-CSS APIs use resolveThemeToken() or ' +
  'useTheme().token().';

/** @param {string} file */
function declaresSourceBuild(file) {
  let pkg;
  try {
    pkg = JSON.parse(fs.readFileSync(file, 'utf-8'));
  } catch {
    return false;
  }
  return DEPENDENCY_FIELDS.some(
    field =>
      pkg?.[field] != null &&
      typeof pkg[field] === 'object' &&
      Object.hasOwn(pkg[field], SOURCE_BUILD_PACKAGE),
  );
}

/**
 * Whether the project that owns `filePath` compiles Astryx source: some
 * package.json from the file's folder up to the repository root (or the
 * filesystem root) declares `@astryxdesign/build`.
 * @param {string} filePath
 */
export function compilesAstryxSource(filePath) {
  let dir = path.dirname(path.resolve(filePath));
  for (;;) {
    if (declaresSourceBuild(path.join(dir, 'package.json'))) return true;
    if (REPOSITORY_ROOT_MARKERS.some(m => fs.existsSync(path.join(dir, m)))) {
      return false;
    }
    const parent = path.dirname(dir);
    if (parent === dir) return false;
    dir = parent;
  }
}

/** @param {any} node */
function staticString(node) {
  if (
    (node?.type === 'StringLiteral' || node?.type === 'Literal') &&
    typeof node.value === 'string'
  ) {
    return node.value;
  }
  if (node?.type === 'TemplateLiteral') {
    // Each static chunk of the template; a use can sit between expressions.
    return (node.quasis ?? [])
      .map((/** @type {any} */ q) => q?.value?.cooked ?? q?.value?.raw ?? '')
      .join('\u0000');
  }
  return undefined;
}

/**
 * Put the TODO on its own line before the stylesheet line of the first use,
 * or directly before the use when an earlier comment ends on that line.
 * @param {string} source
 * @param {string} uncommented
 * @param {number} index
 */
function markStylesheet(source, uncommented, index) {
  const lineStart = source.lastIndexOf('\n', index - 1) + 1;
  const prefix = source.slice(lineStart, index);
  if (prefix !== uncommented.slice(lineStart, index)) {
    return `${source.slice(0, index)}/* ${TODO_TEXT} */ ${source.slice(index)}`;
  }
  const indent = /^[ \t]*/u.exec(prefix)?.[0] ?? '';
  return `${source.slice(0, lineStart)}${indent}/* ${TODO_TEXT} */\n${source.slice(lineStart)}`;
}

/**
 * @param {import('../../../../authoring/codemod/type').AstryxCodemodFile} file
 * @param {import('../../../../authoring/codemod/type').CodemodTransformApi} api
 * @returns {string | undefined}
 */
export default function validateDataTokenOwnership(file, api) {
  if (!file.source.includes('--color-data-')) return undefined;
  const isStylesheet = path.extname(file.path) === '.css';

  if (
    isStylesheet &&
    file.source.includes(GENERATED_THEME_HEADER) &&
    ROOT_DATA_DECLARATION.test(file.source)
  ) {
    throw new Error(
      'This generated theme CSS still emits canonical data defaults at :root. Rebuild it with `astryx theme build`; defaults come from source-compiled dataVars consumers or @astryxdesign/core/astryx.css in prebuilt mode.',
    );
  }

  // Already marked, or the project loads prebuilt Core CSS, which defines
  // every data default (spec:AST-066 FR3).
  if (file.source.includes(TODO_MARKER)) return undefined;
  if (!DIRECT_DATA_VAR.test(file.source)) return undefined;
  if (!compilesAstryxSource(file.path)) return undefined;

  if (isStylesheet) {
    const uncommented = file.source.replace(CSS_COMMENT, comment =>
      comment.replace(/[^\n]/gu, ' '),
    );
    const cssMatch = DIRECT_DATA_VAR.exec(uncommented);
    if (!cssMatch) return undefined;
    return markStylesheet(file.source, uncommented, cssMatch.index);
  }

  const j = api.jscodeshift;
  const root = j(file.source);
  /** @type {any} */
  let found = null;
  /** @param {any} nodePath */
  const inspect = nodePath => {
    const value = staticString(nodePath.node);
    if (
      typeof value === 'string' &&
      DIRECT_DATA_VAR.test(value) &&
      (found == null || nodePath.node.start < found.node.start)
    ) {
      found = nodePath;
    }
  };
  root.find(j.StringLiteral).forEach(inspect);
  root.find(j.Literal).forEach(inspect);
  root.find(j.TemplateLiteral).forEach(inspect);
  if (!found) return undefined;

  // A comment on a node inside JSX children would print as text, so the TODO
  // goes on the nearest enclosing statement.
  let host = found;
  while (host && !j.Statement.check(host.node)) host = host.parent;
  const node = host?.node ?? root.find(j.Program).get('body', 0).node;
  node.comments = node.comments ?? [];
  node.comments.push(j.commentBlock(` ${TODO_TEXT} `, true, false));
  return root.toSource();
}
